/**
 * 生成段的**来源判据**（BUG-035 残留：证据消失后旧生成段不得留存）。
 *
 * ## 侧车怎么区分「生成」与「手写」
 *
 * 侧车里**生成**内容 = 带 nudo 自己的 `@generated` 标记行的段
 * （`// @generated by nudo — do not edit; …`）：core 的 `generatedExportNames`
 * 与 service 的 `collectGeneratedSections` 同口径（标记行的首个记号是
 * `@generated` 且点名 nudo ⇒ 散文里提到 `@generated` 不算）。
 * **手写**内容 = 没有该标记的一切内容（手写 fn 契约、值级 template、注释…），
 * 发射器永不覆盖手写内容。
 *
 * ## 为什么需要「来源」判据
 *
 * 「证据消失 ⇒ 生成段必须被刷新（删掉）」只在**能证明**证据没了时成立：
 * 跨文件证据（`--from` 采集的调用点记录）本轮可能**压根没采集** ⇒
 * 「没看到证据」≠「证据没了」⇒ 不得据此删用户的契约（无证据 ⇒ 无从判断）。
 * **旧**侧车格式的头注释**不记证据范围**（没写这段的证据来自哪里）⇒ 来源
 * 只能从段内容本身推（见下「可证判据」）。现格式记录证据范围（见末节
 * 「判据（BUG-035 收口）」）⇒ 宽域段也能判定。
 *
 * ## 可证判据：单点字面量域 ⇒ 证据必在文件内
 *
 * 今天的发射模型里，**调用点观测一律拓宽**（BUG-021：点观测 ⇒ 基类型；
 * 多值观测域 `union(lit(1), lit(-2))` 是真实观测域，保留字面量并集）。
 * ⇒ **调用点证据产不出「单点字面量」域**（顶层槽是单个 `lit(...)`）。
 * ⇒ 钉住单点字面量的生成段，其证据**只可能**来自**文件内**：
 * `@nudo:case` 域声明（带断言的指令 case）或入口推断（entry@）。
 * ⇒ 对这类段，**当前分析对文件内证据的视野是完整的** ⇒
 * 「今天没有证据」= 「证据没了」⇒ 该段必须被删（刷新）。
 *
 * ## 保守边界（不可证 ⇒ 保留原段，绝不误删）
 *
 * - 顶层槽**不是**单点字面量的**旧**段（没有 `// evidence:` 行）：可能来自
 *   跨文件调用记录（本轮未采集）⇒ 保留；带 `// evidence: external` 的段：保留；
 * - 带 `// derived-from:` 标签的段：证据可能来自 root 契约（root 可能在别的
 *   文件）⇒ 保留；
 * - 段文本装不上（exec 失败 / 非 fn 形态）⇒ 不可证 ⇒ 保留。
 *
 * ## 判据（BUG-035 收口）：侧车**记录证据范围**
 *
 * 上面的推理只对**能证明**证据在文件内的段成立。旧侧车格式不记证据范围 ⇒
 * 宽域段（如 `fn({ x: number() }, number())`）与「`--from` 记录来源的段」
 * 逐字同形 ⇒ 只能保守保留（这就是旧实现的残差）。
 *
 * 现格式：生成段多一行 `// evidence: local|external` ——
 *
 * - `local`：生成该段时**没有**外部 `--from` 记录参与域合成（分析器在
 *   `FunctionAnalysis.externalEvidence` 上打标，发射器落进这一行）⇒ 证据
 *   全部来自本项目分析（模块图 / 文件内指令 case / 入口推断），每次运行都会
 *   重新推导 ⇒ 今天的分析「没有证据」**就是**证据没了 ⇒ 允许删段（宽域也删）。
 * - `external`：混入了使用现场记录（不属于模块图闭包）⇒ 本轮没采集 ≠ 证据没了
 *   ⇒ 保守保留。
 * - **旧侧车没有这一行** ⇒ 退回旧启发式（单点字面量 ⇒ 可证），迁移期零回归：
 *   旧段在下次因内容变化被重写时自动带上标记。
 *
 * 结论：`sectionEvidenceIsInFile` = 无 `derived-from` 标签 且（标记为 local
 * 或（无标记且钉单点字面量））。
 */

import {
  execNudoModule,
  formatConstraint,
  isNudoConstraint,
  refineDiagCount,
  takeRefineDiagsSince,
  type NudoConstraint,
} from "@nudojs/core";

/** 段的**证据范围**（`// evidence:` 行；旧侧车没有该行 ⇒ `undefined`） */
export type EvidenceScope = "local" | "external";

/**
 * 段头记录的**证据范围**（BUG-035 收口点）。
 *
 * `local` = 该段证据全部来自本项目分析（模块图求值 / 文件内指令 case /
 * 入口推断）——每次运行都会重新推导 ⇒ 今天的分析「没有证据」可证「证据没了」。
 * `external` = 混入 `--from` 采集的使用现场调用记录（不属于模块图闭包，
 * 本轮可能压根没采集）⇒ 不可证。
 */
export function sectionEvidenceScope(sectionText: string): EvidenceScope | undefined {
  const m = /^[ \t]*\/\/[ \t]*evidence:[ \t]*(local|external)[ \t]*$/m.exec(sectionText);
  return m === null ? undefined : (m[1] as EvidenceScope);
}

/** 段内是否带 `// derived-from:` 标签（派生段：证据可能来自 root 契约） */
export function sectionHasDerivedFrom(sectionText: string): boolean {
  return /^[ \t]*\/\/[ \t]*derived-from:/m.test(sectionText);
}

/**
 * 段的**顶层槽**（形参位 + 返回位）是否钉住单点字面量（`lit(...)`）。
 *
 * 读法：把段文本当模块求值（`execNudoModule`，与写入前的 round-trip 自检
 * 同一路径）⇒ 拿到该导出的约束 ⇒ 看顶层槽的组合式显示是否以 `lit(` 开头。
 * 读不出来（exec 失败 / 非 fn 形态 / 槽是 shape、union、number()…）⇒ false
 * （不可证 ⇒ 保守保留）。
 */
export function sectionPinsLiteralSlot(sectionText: string, fn: string): boolean {
  const since = refineDiagCount();
  try {
    const exports = execNudoModule(sectionText);
    const v = exports[fn];
    if (!isNudoConstraint(v) || v.fn === undefined) return false;
    const slots: NudoConstraint[] = Object.values(v.fn.params);
    if (v.fn.returns !== undefined) slots.push(v.fn.returns);
    return slots.some((c) => formatConstraint(c).startsWith("lit("));
  } catch {
    return false;
  } finally {
    takeRefineDiagsSince(since); // 读段触发的诊断只清本次增量（不窃在途队列）
  }
}

/**
 * 该生成段的证据是否**可证**在本项目分析闭包内 ⇒ 今天的「无证据」= 证据没了
 * （⇒ 该段必须被刷新/删除）。
 *
 * 判据（按可信度递减）：
 * 1. `// derived-from:` 标签 ⇒ 证据来自 root 契约（root 可能在别的文件）⇒ 不可证；
 * 2. `// evidence: local` ⇒ **侧车自己记下了**证据全在本项目闭包内（生成该段
 *    时没有外部 `--from` 记录参与）⇒ 可证（**宽域段也适用**，这是旧实现的残差）；
 * 3. `// evidence: external` ⇒ 含使用现场记录 ⇒ 不可证；
 * 4. 旧侧车（没有 `// evidence:` 行）⇒ 退回启发式：单点字面量域（见
 *    `sectionPinsLiteralSlot`）⇒ 可证；宽域 ⇒ 不可证（保守保留）。
 */
export function sectionEvidenceIsInFile(sectionText: string, fn: string): boolean {
  if (sectionHasDerivedFrom(sectionText)) return false;
  const scope = sectionEvidenceScope(sectionText);
  if (scope === "local") return true;
  if (scope === "external") return false;
  return sectionPinsLiteralSlot(sectionText, fn);
}
